import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:dtls2/dtls2.dart';

void main() async {
  final dtlsClient = await DtlsClient.bind("::", 0);
  final context = DtlsClientContext(
    verify: false,
    withTrustedRoots: false,
  );
  try {
    final connection = await dtlsClient.connect(
      InternetAddress("::1"),
      5684,
      context,
    );
    connection.send(Uint8List.fromList(utf8.encode('Hello World')));
  } finally {
    await dtlsClient.close();
  }
}
